      "arguments": {
        "video_path": "VIDEO",
        "query": "white T-shirt centered on screen against a blue background, showing all visible openings and tears",
        "timestamps": null,
        "num_frames": 1
      },
      "purpose": "Retrieve a representative frame of the static T-shirt image for direct visual inspection.",
      "depends_on": []
    },
    {
